1	import { timingSafeEqual } from "node:crypto";
2	import { Router } from "express";
3	import type { Db } from "@paperclipai/db";
4	import { and, count, eq, gt, inArray, isNull, sql } from "drizzle-orm";
5	import { heartbeatRuns, instanceUserRoles, invites } from "@paperclipai/db";
6	import type { DeploymentExposure, DeploymentMode } from "@paperclipai/shared";
7	import { readPersistedDevServerStatus, toDevServerHealthStatus } from "../dev-server-status.js";
8	import { logger } from "../middleware/logger.js";
9	import { instanceSettingsService } from "../services/instance-settings.js";
10	import { serverVersion } from "../version.js";
11	import { expressHandler } from "../http/express-adapter.js";
12	import type { Handler } from "../http/types.js";
13	import type { StorageService } from "../storage/types.js";
14	
15	function shouldExposeFullHealthDetails(
16	  actorType: "none" | "board" | "agent" | null | undefined,
17	  deploymentMode: DeploymentMode,
18	) {
19	  if (deploymentMode !== "authenticated") return true;
20	  return actorType === "board" || actorType === "agent";
21	}
22	
23	function hasDevServerStatusToken(providedToken: string | undefined) {
24	  const expectedToken = process.env.PAPERCLIP_DEV_SERVER_STATUS_TOKEN?.trim();
25	  const token = providedToken?.trim();
26	  if (!expectedToken || !token) return false;
27	
28	  const expected = Buffer.from(expectedToken);
29	  const provided = Buffer.from(token);
30	  if (expected.length !== provided.length) return false;
31	  return timingSafeEqual(expected, provided);
32	}
